// Compiles evmap/discovery.md, evmap/screening.md, evmap/ranking.md and evmap/characteristics.md into src/prompts.generated.ts, so the
// package carries them (it starts with no evmap/ beside it) and the files stay the one source.
// Run by `npm run build` and `npm test`.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
// A checkout without evmap/ (the public repository) builds from the generated file it carries.
if (!existsSync(new URL("../evmap/", import.meta.url))) process.exit(0);
const read = (f) => readFileSync(new URL(`../evmap/${f}`, import.meta.url), "utf8");   // whole: src/prompts.ts strips what is for people
const out = `// Generated by scripts/gen-prompts.mjs from evmap/*.md — edit those files, not this one.
export const BUILTIN_PROMPTS = {
  screening: ${JSON.stringify(read("screening.md"))},
  ranking: ${JSON.stringify(read("ranking.md"))},
  discovery: ${JSON.stringify(read("discovery.md"))},
  characteristics: ${JSON.stringify(read("characteristics.md"))},
} as const;
`;
writeFileSync(new URL("../src/prompts.generated.ts", import.meta.url), out);
